func (h *H) Export(w http.ResponseWriter, r *http.Request) {
  w.Header().Set("Content-Type", "text/csv")
  cw := csv.NewWriter(w)
  rows, err := h.db.Query(r.Context(), exportQ, cust(r))
  if err != nil { http.Error(w, "error", 500); return }
  defer rows.Close()
  for rows.Next() { var s Shipment; rows.Scan(&s.ID, &s.Status, &s.ETA); cw.Write(s.Record()); if n++; n%1000 == 0 { cw.Flush() } }
  cw.Flush()
}
